const body = $json.body ?? $json;
const email = typeof body.caption_email === 'string' ? body.caption_email.trim().toLowerCase() : '';
const emailPattern = /^[a-zA-Z0-9.!#$%&'*+\/=?^_`{|}~-]+@[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)+$/;
const captionEmail = emailPattern.test(email) ? email : null;
const imageBase64 = typeof body.image?.base64 === 'string' ? body.image.base64 : '';
const maxBase64Length = Math.ceil((10 * 1024 * 1024) * 4 / 3) + 4;
const base64Pattern = /^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/;
const processingId = typeof body.processing_id === 'string' && body.processing_id.length <= 128 ? body.processing_id : null;
const invalid = reasonCode => [{ json: { valid: false, processing_id: processingId, validation_error: { status: 'REJECTED', verdict: 'UNCLEAR', reason_code: reasonCode } } }];
if (typeof body.processing_id !== 'string' || body.processing_id.length < 1 || body.processing_id.length > 128 || typeof body.message_id !== 'string' || body.message_id.length < 1 || body.message_id.length > 256 || body.source !== 'whatsapp') return invalid('INVALID_EVENT_IDENTITY');
if (!body.image || !['image/jpeg', 'image/png', 'image/webp'].includes(body.image.mime_type) || imageBase64.length === 0 || imageBase64.length > maxBase64Length || !base64Pattern.test(imageBase64)) return invalid('INVALID_IMAGE_PAYLOAD');
return [{ json: { ...body, valid: true, caption_email: captionEmail, image: { ...body.image, base64: imageBase64 } } }];

const body = $json;
const state = $getWorkflowStaticData('global');
const now = Date.now();
const ttlMs = 24 * 60 * 60 * 1000;
const key = `${body.source}:${body.message_id}`;
const processed = state.processed_messages ?? {};
for (const [storedKey, seenAt] of Object.entries(processed)) {
  if (!Number.isInteger(seenAt) || now - seenAt > ttlMs) delete processed[storedKey];
}
const duplicate = Object.prototype.hasOwnProperty.call(processed, key);
if (!duplicate) processed[key] = now;
state.processed_messages = processed;
return [{ json: { ...body, idempotency: { key, duplicate } } }];

const original = $('Validate Event').first().json;
const ocrResult = $json;
const fields = ocrResult.fields ?? {};
const emailPattern = /^[a-zA-Z0-9.!#$%&'*+\/=?^_`{|}~-]+@[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)+$/;
const ocrEmail = typeof fields.email === 'string' && emailPattern.test(fields.email.trim().toLowerCase()) ? fields.email.trim().toLowerCase() : null;
const captionEmail = original.caption_email || null;
const emailCandidates = [...new Set([captionEmail, ocrEmail].filter(Boolean))];
const lookupEmail = captionEmail || ocrEmail;
const transactionId = typeof fields.transaction_id === 'string' && /^[A-Za-z0-9][A-Za-z0-9_-]{3,127}$/.test(fields.transaction_id.trim()) ? fields.transaction_id.trim() : null;
const description = typeof fields.description === 'string' && fields.description.trim().length <= 1000 ? fields.description.trim() : null;
const amountValid = Number.isInteger(fields.amount_cents) && fields.amount_cents > 0;
const dateValid = typeof fields.payment_date === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(fields.payment_date);
const relativeToday = !dateValid && typeof ocrResult.raw_text === 'string' && /\btoday\b/i.test(ocrResult.raw_text);
let todayDate = null;
if (relativeToday && typeof original.received_at === 'string') {
  const parsedReceivedAt = new Date(original.received_at);
  const timezone = typeof original.stripe_timezone === 'string' && original.stripe_timezone ? original.stripe_timezone : 'UTC';
  if (!Number.isNaN(parsedReceivedAt.getTime())) {
    try {
      todayDate = new Intl.DateTimeFormat('en-CA', { timeZone: timezone, year: 'numeric', month: '2-digit', day: '2-digit' }).format(parsedReceivedAt);
    } catch (_error) {
      todayDate = null;
    }
  }
}

const minutes = Number(fields.minutes);
const hour = Number(fields.payment_hour);
const month = Number(fields.payment_month);
const day = Number(fields.payment_day);
const minutesValid = Number.isInteger(minutes) && minutes >= 0 && minutes <= 59;
const hourValid = Number.isInteger(hour) && hour >= 0 && hour <= 23;
const monthValid = Number.isInteger(month) && month >= 1 && month <= 12;
const dayValid = Number.isInteger(day) && day >= 1 && day <= 31;
let inferredMonthDayDate = null;
if (!dateValid && monthValid && dayValid && typeof original.received_at === 'string') {
  const receivedAt = new Date(original.received_at);
  const timezone = typeof original.stripe_timezone === 'string' && original.stripe_timezone ? original.stripe_timezone : 'UTC';
  if (!Number.isNaN(receivedAt.getTime())) {
    try {
      const parts = new Intl.DateTimeFormat('en-CA', { timeZone: timezone, year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(receivedAt);
      const receivedYear = Number(parts.find(part => part.type === 'year')?.value);
      const receivedMonth = Number(parts.find(part => part.type === 'month')?.value);
      const receivedDay = Number(parts.find(part => part.type === 'day')?.value);
      if (Number.isInteger(receivedYear) && Number.isInteger(receivedMonth) && Number.isInteger(receivedDay)) {
        let inferredYear = receivedYear;
        const candidateDay = Date.UTC(inferredYear, month - 1, day);
        const receivedDayStart = Date.UTC(receivedYear, receivedMonth - 1, receivedDay);
        if (candidateDay > receivedDayStart) inferredYear -= 1;
        inferredMonthDayDate = `${inferredYear}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
      }
    } catch (_error) {
      inferredMonthDayDate = null;
    }
  }
}
const normalizedPaymentDate = dateValid ? fields.payment_date : (todayDate || inferredMonthDayDate);
const canQueryStripe = original.stripe_verification_enabled === true;
let verification = null;
if (original.stripe_verification_enabled !== true) verification = { status: 'SKIPPED', verdict: 'UNCLEAR', reason_code: 'STRIPE_DISABLED' };
else verification = { status: 'PENDING', verdict: 'UNCLEAR', reason_code: 'STRIPE_LOOKUP_PENDING' };
return [{ json: { processing_id: original.processing_id, ready_for_stripe: canQueryStripe, ocr_result: ocrResult, verification, stripe_request: { processing_id: original.processing_id, email: lookupEmail, email_candidates: emailCandidates, transaction_id: transactionId, description: description, amount_cents: amountValid ? fields.amount_cents : null, payment_date: normalizedPaymentDate, payment_month: monthValid ? month : null, payment_day: dayValid ? day : null, minutes: minutesValid ? minutes : null, payment_hour: hourValid ? hour : null, currency: 'usd', payment_method_type: 'cashapp' } } }];
